"use client";
import { useState } from 'react';
export default function EcommerceAI() {
  const [cart,setCart]=useState<any[]>([]);
  return (<div className="min-h-screen bg-[#0a0a0f] text-white p-8"><h1 className="text-3xl font-bold">Ecommerce AI — 200 Providers</h1><p className="text-slate-400 mt-2">Recomendações AI com 200 providers + embeddings + UAI image</p><div className="mt-6 grid grid-cols-4 gap-4">{[1,2,3,4].map(i=>(<div key={i} className="p-4 rounded-xl bg-[#11111b] border border-[#1e1e2e]"><div className="h-32 bg-[#1e1e2e] rounded-lg"></div><div className="mt-2 font-bold">Produto {i}</div><div className="text-slate-400 text-sm">AI recomenda com 200 providers</div><button onClick={()=>setCart([...cart, i])} className="mt-2 px-4 py-1 rounded bg-white text-black text-sm">Add</button></div>))}</div><div className="mt-6 p-4 rounded-xl bg-[#11111b] border border-[#1e1e2e]">Carrinho: {cart.length} itens — AI recomendações via /v1/chat/completions 200 providers</div></div>);
}

